\documentclass{article}
\usepackage{booktabs}
\usepackage{multirow}
\usepackage{array}
\usepackage{caption}

\begin{document}

\begin{table}[h]
\centering
\caption{Exemplar tools for each category.}
\label{tab:tool_categories}
\begin{tabular}{p{4cm}p{6cm}}
\toprule
\textbf{Category} & \textbf{Exemplar Tools} \\
\midrule
Knowledge Access & 
\begin{itemize}
\setlength\itemsep{0em}
\item SQL and SPARQL executors for structured knowledge bases
\item Search engine tools over the Internet
\item Retrieval-augmented generation systems
\end{itemize} \\
\addlinespace
Computation Activities & 
\begin{itemize}
\setlength\itemsep{0em}
\item Calculator for mathematical calculations
\item Python programs for reasoning tasks
\item Business tools (Google Sheets, financial, medical, education domains)
\end{itemize} \\
\addlinespace
Interaction with the World & 
\begin{itemize}
\setlength\itemsep{0em}
\item Weather APIs for real-time information
\item Calendar and email management tools
\item Physical activity tools (Minecraft, cooking, plotting, chemical research)
\end{itemize} \\
\addlinespace
Non-textual Modalities & 
\begin{itemize}
\setlength\itemsep{0em}
\item Image processing APIs (cat image APIs)
\item Audio tools (Spotify music APIs)
\item Visual QA systems
\end{itemize} \\
\addlinespace
Special-skilled LMs & 
\begin{itemize}
\setlength\itemsep{0em}
\item QA models for factoid details
\item Machine translation models
\item Multiple neural models from platforms like HuggingFace
\end{itemize} \\
\bottomrule
\end{tabular}
\end{table}

\end{document}
