\begin{tabular}{p{3cm}p{2.5cm}p{2cm}p{2cm}p{2cm}}
\toprule
\textbf{Benchmark} & \textbf{Tool Sources} & \textbf{Example Curation} & \textbf{Executable} & \textbf{Domains} \\
\midrule
ToolQA & Existing datasets & Human annotated & Yes & Limited \\
ToolLLM & Public APIs & LM synthesized & $\times$ & Multiple \\
API-Bank & Scraped APIs & Human annotated & Yes & Financial \\
ToolAlpaca & RESTful APIs & LM synthesized & $\times$ & General \\
HuggingGPT & HF models & LM synthesized & $\times$ & ML tasks \\
ToolBench & OpenAI plugins & LM synthesized & $\times$ & Various \\
Toolformer & Web search & Human annotated & Yes & Knowledge \\
ToolAug & Augmented datasets & Human annotated & Yes & Limited \\
ToolEval & Mixed sources & Mixed & $\times$ & Comprehensive \\
\bottomrule
\end{tabular}
\end{table}

\end{document}

