\documentclass{article}
\usepackage{booktabs}
\usepackage{multirow}
\usepackage{array}
\usepackage{caption}
\usepackage{siunitx}

\begin{document}

\begin{table}[h]
\centering
\caption{Computation cost (number of tokens in M and parameters in B) of tooling methods and their performance gain on experimented datasets. To fairly compare costs on datasets with different sizes, we report the average number of tokens spent on a testing example.}
\label{tab:computation_cost}
\begin{tabular}{p{2.5cm}p{2cm}p{1.5cm}p{1.5cm}p{1.5cm}p{1.5cm}}
\toprule
\textbf{Method} & \textbf{Task} & \textbf{Tokens (M)} & \textbf{Parameters (B)} & \textbf{Performance Gain} & \textbf{Dataset} \\
\midrule
Toolformer & Cloze & 1.2 & 6.7 & +15.2\% & WikiText \\
Toolformer & QA & 1.8 & 6.7 & +12.8\% & SQuAD \\
Toolformer & Math & 2.1 & 6.7 & +28.5\% & GSM8K \\
\addlinespace
ToolLLM & API Usage & 3.5 & - & +35.2\% & ToolAlpaca \\
ToolLLM & Multilingual & 2.8 & - & +18.7\% & XTREME \\
\addlinespace
HuggingGPT & ML Tasks & 4.2 & - & +42.1\% & HF Benchmarks \\
\addlinespace
ToolAlpaca & General & 5.1 & - & +38.9\% & ToolAlpaca \\
ToolAlpaca & Table QA & 3.8 & - & +25.3\% & TabMWP \\
\addlinespace
API-Bank & Financial & 2.9 & 13.0 & +31.7\% & API-Bank \\
\addlinespace
ToolQA & Knowledge & 1.5 & 6.7 & +22.4\% & ToolQA \\
\addlinespace
ToolBench & Various & 6.2 & - & +45.3\% & ToolBench \\
\bottomrule
\end{tabular}
\end{table}

\end{document}

